        FormFieldSetting.objects.get_or_create(form_key="pm_dashboard", field_key='activity', defaults={"label":'Recent Activity', "help_text":'Recent recorded changes for actively managed properties. Open an item to review its property.', "option_labels":{}})
        self.stdout.write(self.style.SUCCESS("PM dashboard settings initialized; existing edits preserved."))
